using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using Microsoft.Build.Framework;
using Microsoft.Build.Utilities;

namespace Flowthru.Extensions.Python.Build;

/// <summary>
/// MSBuild task that exports C# schema metadata to Python schema files.
/// </summary>
/// <remarks>
/// <para>
/// <strong>Phase 5 implementation:</strong>
/// Reads the SchemaManifest generated by SchemaInterfaceGenerator and emits
/// corresponding Python dataclass files to _generated/flowthru_schemas/.
/// </para>
/// <para>
/// <strong>Invoked from:</strong> Flowthru.Extensions.Python.targets AfterBuild
/// </para>
/// </remarks>
public class PythonSchemaExportTask : Microsoft.Build.Utilities.Task
{
  /// <summary>
  /// Path to the compiled assembly containing the schema manifest.
  /// </summary>
  [Required]
  public string AssemblyPath { get; set; } = string.Empty;

  /// <summary>
  /// Directory where Python schema files will be generated.
  /// </summary>
  [Required]
  public string OutputDirectory { get; set; } = string.Empty;

  public override bool Execute()
  {
    try
    {
      Log.LogMessage(MessageImportance.High, $"Exporting Python schemas from {AssemblyPath}");

      if (!File.Exists(AssemblyPath))
      {
        Log.LogWarning($"Assembly not found: {AssemblyPath}. Skipping Python schema export.");
        return true; // Not a hard failure
      }

      // Load assembly
      var assembly = Assembly.LoadFrom(AssemblyPath);

      // Find SchemaManifest type
      var manifestType = assembly.GetType("Flowthru.Generated.SchemaManifest.SchemaManifest");
      if (manifestType == null)
      {
        Log.LogMessage(
          MessageImportance.Low,
          "No SchemaManifest found. No [FlowthruSchema] types to export."
        );
        return true; // Not an error - project may not have schemas
      }

      // Get Schemas array
      var schemasField = manifestType.GetField(
        "Schemas",
        BindingFlags.Public | BindingFlags.Static
      );
      if (schemasField == null)
      {
        Log.LogWarning("SchemaManifest.Schemas field not found.");
        return true;
      }

      var schemas = schemasField.GetValue(null) as Array;
      if (schemas == null || schemas.Length == 0)
      {
        Log.LogMessage(MessageImportance.Low, "No schemas to export.");
        return true;
      }

      // Create output directory
      Directory.CreateDirectory(OutputDirectory);

      // Generate Python files
      int exportedCount = 0;
      var schemaInfoType = assembly.GetType("Flowthru.Generated.SchemaManifest.SchemaInfo");
      var propertyInfoType = assembly.GetType("Flowthru.Generated.SchemaManifest.PropertyInfo");

      foreach (var schema in schemas)
      {
        if (schema == null)
          continue;

        var name = schemaInfoType!.GetProperty("Name")!.GetValue(schema) as string;
        var ns = schemaInfoType.GetProperty("Namespace")!.GetValue(schema) as string;
        var isFlat = (bool)schemaInfoType.GetProperty("IsFlat")!.GetValue(schema)!;
        var properties = schemaInfoType.GetProperty("Properties")!.GetValue(schema) as Array;

        if (string.IsNullOrEmpty(name) || properties == null)
          continue;

        var pythonCode = GeneratePythonSchema(name, ns, isFlat, properties, propertyInfoType!);
        var outputPath = Path.Combine(OutputDirectory, $"{ToSnakeCase(name)}.py");

        File.WriteAllText(outputPath, pythonCode, Encoding.UTF8);
        exportedCount++;

        Log.LogMessage(MessageImportance.Normal, $"  Generated {Path.GetFileName(outputPath)}");
      }

      // Generate __init__.py
      GenerateInitFile(OutputDirectory, schemas, schemaInfoType!);

      Log.LogMessage(
        MessageImportance.High,
        $"Exported {exportedCount} Python schema files to {OutputDirectory}"
      );

      return true;
    }
    catch (Exception ex)
    {
      Log.LogErrorFromException(ex, showStackTrace: true);
      return false;
    }
  }

  private string GeneratePythonSchema(
    string name,
    string? ns,
    bool isFlat,
    Array properties,
    Type propertyInfoType
  )
  {
    var sb = new StringBuilder();

    sb.AppendLine($"# Auto-generated from {name}.cs — do not edit");
    sb.AppendLine("# Phase 5: Python schema export");
    sb.AppendLine("from dataclasses import dataclass");
    sb.AppendLine("from typing import Optional");
    sb.AppendLine();
    sb.AppendLine();
    sb.AppendLine("@dataclass");
    sb.AppendLine($"class {name}:");
    sb.AppendLine($"    \"\"\"");
    sb.AppendLine($"    Schema: {ns}.{name}");
    sb.AppendLine($"    Type: {(isFlat ? "Flat" : "Nested")}");
    sb.AppendLine($"    \"\"\"");

    if (properties.Length == 0)
    {
      sb.AppendLine("    pass");
    }
    else
    {
      foreach (var prop in properties)
      {
        if (prop == null)
          continue;

        var propName = propertyInfoType.GetProperty("Name")!.GetValue(prop) as string;
        var propTypeName = propertyInfoType.GetProperty("TypeName")!.GetValue(prop) as string;

        if (string.IsNullOrEmpty(propName) || string.IsNullOrEmpty(propTypeName))
          continue;

        var pythonType = MapCSharpTypeToPython(propTypeName);
        sb.AppendLine($"    {ToSnakeCase(propName)}: {pythonType}");
      }
    }

    sb.AppendLine();
    sb.AppendLine();
    sb.AppendLine("# DataFrame dtype specification for pd.read_csv / pd.DataFrame");
    sb.AppendLine("DTYPE_SPEC = {");

    foreach (var prop in properties)
    {
      if (prop == null)
        continue;

      var propName = propertyInfoType.GetProperty("Name")!.GetValue(prop) as string;
      var propTypeName = propertyInfoType.GetProperty("TypeName")!.GetValue(prop) as string;

      if (string.IsNullOrEmpty(propName) || string.IsNullOrEmpty(propTypeName))
        continue;

      var dtypeSpec = MapCSharpTypeToDtype(propTypeName);
      sb.AppendLine($"    '{ToSnakeCase(propName)}': '{dtypeSpec}',");
    }

    sb.AppendLine("}");

    return sb.ToString();
  }

  private void GenerateInitFile(string outputDirectory, Array schemas, Type schemaInfoType)
  {
    var sb = new StringBuilder();
    sb.AppendLine("# Auto-generated flowthru_schemas package");
    sb.AppendLine("# Phase 5: Python schema export");
    sb.AppendLine();
    sb.AppendLine("\"\"\"");
    sb.AppendLine("Generated Python schemas from C# [FlowthruSchema] types.");
    sb.AppendLine("Import these types in your Python steps for IDE support.");
    sb.AppendLine("\"\"\"");
    sb.AppendLine();

    var schemaNames = new List<string>();
    foreach (var schema in schemas)
    {
      if (schema == null)
        continue;

      var name = schemaInfoType.GetProperty("Name")!.GetValue(schema) as string;
      if (!string.IsNullOrEmpty(name))
      {
        schemaNames.Add(name);
        sb.AppendLine($"from .{ToSnakeCase(name)} import {name}, DTYPE_SPEC as {name}_DTYPE");
      }
    }

    sb.AppendLine();
    sb.AppendLine("__all__ = [");
    foreach (var name in schemaNames)
    {
      sb.AppendLine($"    '{name}',");
      sb.AppendLine($"    '{name}_DTYPE',");
    }
    sb.AppendLine("]");

    File.WriteAllText(Path.Combine(outputDirectory, "__init__.py"), sb.ToString(), Encoding.UTF8);
  }

  private string MapCSharpTypeToPython(string csharpType)
  {
    // Handle nullable types
    var isNullable = false;
    if (csharpType.StartsWith("System.Nullable<"))
    {
      isNullable = true;
      // Extract inner type: System.Nullable<int> -> int
      var start = csharpType.IndexOf('<') + 1;
      var end = csharpType.LastIndexOf('>');
      csharpType = csharpType.Substring(start, end - start);
    }

    // Handle System.Collections.Generic.IEnumerable<T>
    if (csharpType.StartsWith("System.Collections.Generic.IEnumerable<"))
    {
      var start = csharpType.IndexOf('<') + 1;
      var end = csharpType.LastIndexOf('>');
      var elementType = csharpType.Substring(start, end - start);
      var pythonElementType = MapCSharpTypeToPython(elementType);
      return $"list[{pythonElementType}]";
    }

    var baseType = csharpType switch
    {
      "int" or "System.Int32" => "int",
      "long" or "System.Int64" => "int",
      "short" or "System.Int16" => "int",
      "byte" or "System.Byte" => "int",
      "double" or "System.Double" => "float",
      "float" or "System.Single" => "float",
      "decimal" or "System.Decimal" => "float",
      "bool" or "System.Boolean" => "bool",
      "string" or "System.String" => "str",
      "System.DateTime" => "datetime",
      "System.DateTimeOffset" => "datetime",
      "System.TimeSpan" => "timedelta",
      "System.Guid" => "str",
      "byte[]" or "System.Byte[]" => "bytes",
      _ => "object", // Fallback for complex types
    };

    return isNullable ? $"Optional[{baseType}]" : baseType;
  }

  private string MapCSharpTypeToDtype(string csharpType)
  {
    // Handle nullable - pandas handles nullability separately
    if (csharpType.StartsWith("System.Nullable<"))
    {
      var start = csharpType.IndexOf('<') + 1;
      var end = csharpType.LastIndexOf('>');
      csharpType = csharpType.Substring(start, end - start);
    }

    return csharpType switch
    {
      "int" or "System.Int32" => "int32",
      "long" or "System.Int64" => "int64",
      "short" or "System.Int16" => "int16",
      "byte" or "System.Byte" => "uint8",
      "double" or "System.Double" => "float64",
      "float" or "System.Single" => "float32",
      "decimal" or "System.Decimal" => "float64",
      "bool" or "System.Boolean" => "bool",
      "string" or "System.String" => "object",
      "System.DateTime" => "datetime64[ns]",
      "System.DateTimeOffset" => "datetime64[ns, UTC]",
      "System.Guid" => "object",
      _ => "object",
    };
  }

  private string ToSnakeCase(string pascalCase)
  {
    if (string.IsNullOrEmpty(pascalCase))
      return pascalCase;

    var sb = new StringBuilder();
    sb.Append(char.ToLowerInvariant(pascalCase[0]));

    for (int i = 1; i < pascalCase.Length; i++)
    {
      var c = pascalCase[i];
      if (char.IsUpper(c))
      {
        sb.Append('_');
        sb.Append(char.ToLowerInvariant(c));
      }
      else
      {
        sb.Append(c);
      }
    }

    return sb.ToString();
  }
}
